-- Откат 0046: возвращает тексты главной, какими они были до перехода на ТЗ «тренажёр ЕГЭ с ИИ».
-- Блоки возвращаются только если лежат в новом виде (по md5 из миграции не проверяем: откат делает человек намеренно).
update public.content_blocks
   set data = $j${"title":"Подготовка к ЕГЭ с ИИ-репетитором, который объясняет, а не решает за тебя","highlight":"ИИ-репетитором","subtitle":"Диагностика уровня, персональный план, задания из открытого банка ФИПИ, уровневые подсказки и проверка сочинений по критериям. Без списывания — с пониманием."}$j$::jsonb, updated_at = now()
 where key = 'hero';

update public.content_blocks
   set data = $j$[{"icon":"target","t":"Диагностика уровня","d":"8–12 заданий — и понятно, с чего начинать."},{"icon":"book","t":"Персональный план","d":"Что повторить сегодня, сколько тренироваться на неделе."},{"icon":"list","t":"Задания формата ЕГЭ","d":"Открытый банк ФИПИ, мгновенная проверка по эталону."},{"icon":"chat","t":"ИИ-объяснения без готовых ответов","d":"Наводит на решение вопросами, а не выдаёт результат."},{"icon":"check","t":"Проверка сочинений и развёрнутых ответов","d":"По критериям, с чёткими баллами по каждому пункту."},{"icon":"timer","t":"Пробные варианты","d":"Таймер, часть 1 и часть 2 — как на настоящем экзамене."}]$j$::jsonb, updated_at = now()
 where key = 'capabilities';

update public.content_blocks
   set data = $j$[{"n":"01","icon":"target","t":"Диагностика","d":"8–12 заданий по предмету, 7–10 минут. Без подсказок — так точнее видно, что уже знаешь, а что нет."},{"n":"02","icon":"book","t":"Персональный план","d":"На основе результатов — что повторить сегодня, сколько тренировок на неделе и когда пробник."},{"n":"03","icon":"chat","t":"Тренировки с ИИ","d":"Решаешь задания, при затруднении — уровневые подсказки и объяснение темы, без готового ответа."},{"n":"04","icon":"timer","t":"Пробный вариант","d":"Часть 1 и часть 2 на время, без подсказок — как на настоящем экзамене. Разбор после сдачи."}]$j$::jsonb, updated_at = now()
 where key = 'process';

update public.content_blocks
   set data = $j$[{"q":"Это официальный ресурс ФИПИ?","a":"Нет. Это учебный проект, который ориентируется на формат Открытого банка заданий ФИПИ и демоверсии ЕГЭ, но не является официальным ресурсом ФИПИ или Рособрнадзора."},{"q":"ИИ даст готовый ответ, если попросить?","a":"Нет, по конструкции. Даже если явно попросить — ИИ объяснит тему, задаст наводящий вопрос или разберёт похожий пример, но не назовёт финальный ответ твоего задания."},{"q":"Нужно заниматься каждый день?","a":"Нет. На онбординге ты сам выбираешь темп — от 10 минут до часа в день, план подстраивается под это время."},{"q":"Прогресс сохранится, если я закрою вкладку?","a":"Да, после регистрации план, диагностика и история попыток сохраняются в твоём аккаунте и доступны при следующем входе."}]$j$::jsonb, updated_at = now()
 where key = 'faq';

update public.content_blocks
   set data = jsonb_set(
         jsonb_set(coalesce(data, '{}'::jsonb), '{pages,home,title}', to_jsonb($j$ЕГЭ·ПРО — тренажёр с ИИ-репетитором$j$::text), true),
         '{pages,home,description}', to_jsonb($j$ЕГЭ·ПРО — тренажёр для подготовки к ЕГЭ с ИИ-репетитором. Задания из Открытого банка ФИПИ: математика, русский язык, физика, обществознание, биология, химия и другие предметы.$j$::text), true),
       updated_at = now()
 where key = 'seo';
